            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
in_demo=G['Demo pair 1 input']
out_demo=G['Demo pair 1 output']
# Find connected components of 1s in demo input
def comps(G):
    H=[row[:] for row in G]; seen=set(); comps=[]
    rows,cols=len(H),len(H[0])
    dirs=[(-1,0),(1,0),(0,-1),(0,1)]
    for i in range(rows):
        for j in range(cols):
            if H[i][j]==1 and (i,j) not in seen:
                cur=[(i,j)]; q=[(i,j)]; seen.add((i,j))
                while q:
                    a,b=q.pop(0); for da,db in dirs:
                        na,nb=a+da,b+db
                        if 0<=na<rows and 0<=nb<cols and H[na][nb]==1 and (na,nb) not in seen:
                            seen.add((na,nb)); cur.append((na,nb)); q.append((na,nb))
                comps.append(cur)
    return comps
